class Solution {
public:
    int triangularSum(vector<int>& nums) {
        for (int m = nums.size() - 1; m > 0; m--) {
            for (int i = 0; i < m; i++) {
                nums[i] = (nums[i] + nums[i + 1]) % 10;
            }
        }
        return nums[0];
    }
};

class Solution {
    public int triangularSum(int[] nums) {
        for (int m = nums.length - 1; m > 0; m--) {
            for (int i = 0; i < m; i++) {
                nums[i] = (nums[i] + nums[i + 1]) % 10;
            }
        }
        return nums[0];
    }
}

/**
