var triangularSum = function(nums) {
    for (let m = nums.length - 1; m > 0; m--) {
        for (let i = 0; i < m; i++) {
            nums[i] = (nums[i] + nums[i + 1]) % 10;
        }
    }
    return nums[0];
};
